def beside_rect(parent_rect, screens, width, height, gap=12):
    """Choose a full-size side position, or visible overlap on parent's screen."""
    selected = placement_for(parent_rect, screens)["monitor"]
    screen = next(s for s in screens if s["monitor"] == selected)
    left, top, right, bottom = screen["work"]
    width = max(1, min(int(width), right - left))
    height = max(1, min(int(height), bottom - top))
    px1, py1, px2, py2 = parent_rect
    if right - px2 - gap >= width:
        x = px2 + gap
    elif px1 - left - gap >= width:
        x = px1 - gap - width
    else:
        x = px1 + ((px2 - px1) - width) // 2
    y = py1
    return (max(left, min(x, right - width)),
            max(top, min(y, bottom - height)), width, height)


def place_beside(dialog, parent):
    """Position an app-owned dialog once, after Windows has mapped it."""
    import tkinter as tk

    def place():
        try:
            if not dialog.winfo_exists() or not parent.winfo_exists():
                return
            api, handle, rect = _window_rect(dialog)
            _, _, parent_rect = _window_rect(parent)
            x, y, width, height = beside_rect(
                parent_rect, monitors(), rect[2] - rect[0], rect[3] - rect[1])
            # Allow fitting a smaller display without changing larger-screen minima.
            min_width, min_height = dialog.minsize()
            border_width = max(0, rect[2] - rect[0] - dialog.winfo_width())
            border_height = max(0, rect[3] - rect[1] - dialog.winfo_height())
            dialog.minsize(min(min_width, max(1, width - border_width)),
                           min(min_height, max(1, height - border_height)))
            if not api.SetWindowPos(handle, None, x, y, width, height, 0x14):
                raise OSError("Dialog positioning unavailable")
        except (OSError, AttributeError, RuntimeError, tk.TclError):
            pass

    if dialog.winfo_ismapped():
        dialog.after_idle(place)
    else:
        def mapped(event):
            if event.widget is dialog:
                dialog.unbind("<Map>", binding)
                dialog.after_idle(place)

        binding = dialog.bind("<Map>", mapped, add="+")
